const body = $json.body ?? $json;
const message = String(body.message ?? '').replace(/[<>]/g, ' ').trim().slice(0, 500);
const locale = ['es','en','fr','pt','de'].includes(String(body.locale ?? 'es').split('-')[0]) ? String(body.locale).split('-')[0] : 'es';
const supplied = body.location;
const validLocation = Number.isFinite(Number(supplied?.lat)) && Number.isFinite(Number(supplied?.lng)) && Math.abs(Number(supplied.lat)) <= 90 && Math.abs(Number(supplied.lng)) <= 180;
const location = validLocation ? { lat: Number(supplied.lat), lng: Number(supplied.lng) } : { lat: 9.9281, lng: -84.0907 };
const newsTerms = /clima|lluvia|tormenta|inund/i.test(message) ? '(Costa Rica) (clima OR lluvia OR inundacion)' : /accidente|carretera|tr[aá]fico|vial/i.test(message) ? '(Costa Rica) (accidente OR carretera OR trafico)' : /turis|visitar|playa|parque|museo/i.test(message) ? '(Costa Rica) (turismo OR playa OR parque)' : '"Costa Rica"';
const weatherUrl = `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current=temperature_2m,precipitation,rain,wind_speed_10m,weather_code&hourly=visibility&forecast_days=1&timezone=America%2FCosta_Rica`;
const newsUrl = `https://api.gdeltproject.org/api/v2/doc/doc?query=${encodeURIComponent(newsTerms)}&mode=artlist&maxrecords=8&timespan=3d&sort=datedesc&format=json`;
const googleNewsUrl = `https://news.google.com/rss/search?q=${encodeURIComponent(newsTerms.replace(/[()]/g, ''))}&hl=es-419&gl=CR&ceid=CR:es-419`;
const imnAlertsUrl = 'https://cap-sources.s3.amazonaws.com/cr-imn-es/rss.xml';
const wikiLanguage = locale === 'de' ? 'de' : locale === 'en' ? 'en' : locale === 'fr' ? 'fr' : locale === 'pt' ? 'pt' : 'es';
const placesUrl = `https://${wikiLanguage}.wikipedia.org/w/api.php?action=query&list=geosearch&gscoord=${location.lat}%7C${location.lng}&gsradius=10000&gslimit=10&format=json`;
return [{ json: { message, locale, location, usedDefaultLocation: !validLocation, weatherUrl, newsUrl, googleNewsUrl, imnAlertsUrl, placesUrl } }];

const request = $('Prepare Public Queries').first().json;
const weatherRaw = $('Fetch Current Weather').first().json ?? {};
const newsRaw = $('Fetch Costa Rica News').first().json ?? {};
const placesRaw = $('Fetch Nearby Places').first().json ?? {};
const rssItems = $('Fetch Google News RSS').all().map(item => item.json ?? {});
const imnItems = $('Fetch IMN Alerts RSS').all().map(item => item.json ?? {});
const current = weatherRaw.current ?? {};
const weather = current.time ? {
  provider: 'open-meteo',
  temperatureC: Number.isFinite(Number(current.temperature_2m)) ? Number(current.temperature_2m) : null,
  precipitationMm: Number.isFinite(Number(current.precipitation)) ? Number(current.precipitation) : null,
  rainMm: Number.isFinite(Number(current.rain)) ? Number(current.rain) : null,
  windKmh: Number.isFinite(Number(current.wind_speed_10m)) ? Number(current.wind_speed_10m) : null,
  weatherCode: current.weather_code ?? null,
  visibilityM: Array.isArray(weatherRaw.hourly?.visibility) ? weatherRaw.hourly.visibility[0] : null,
  observedAt: current.time,
  sourceUrl: 'https://open-meteo.com/'
} : null;
const imnAlerts = imnItems.slice(0, 3).map((alert, index) => {
  const url = String(alert.link ?? alert.guid ?? '').slice(0, 800);
  const description = String(alert.contentSnippet ?? alert.content ?? alert.description ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 900);
  return {
    id: `imn-${index}-${url.slice(-30)}`,
    title: String(alert.title ?? '').replace(/[<>]/g, ' ').slice(0, 220),
    description,
    url,
    publishedAt: alert.isoDate ?? alert.pubDate ?? null,
    sourceType: 'official_weather_alert',
    provider: 'imn-costa-rica'
  };
}).filter(item => item.title && item.url);
const gdeltNews = (Array.isArray(newsRaw.articles) ? newsRaw.articles : []).slice(0, 8).map((article, index) => ({
  id: `gdelt-${index}-${String(article.url ?? '').slice(-30)}`,
  title: String(article.title ?? '').replace(/[<>]/g, ' ').slice(0, 220),
  url: String(article.url ?? '').slice(0, 800),
  domain: String(article.domain ?? '').slice(0, 180),
  language: String(article.language ?? '').slice(0, 40),
  publishedAt: article.seendate ?? null,
  sourceType: 'external_news',
  provider: 'gdelt'
})).filter(item => item.title && item.url);
const rssNews = rssItems.slice(0, 8).map((article, index) => {
  const url = String(article.link ?? article.guid ?? '').slice(0, 800);
  let domain = '';
  try { domain = new URL(url).hostname; } catch {}
  return {
    id: `google-news-${index}-${url.slice(-30)}`,
    title: String(article.title ?? '').replace(/[<>]/g, ' ').slice(0, 220),
    url,
    domain,
    language: 'es',
    publishedAt: article.isoDate ?? article.pubDate ?? null,
    sourceType: 'external_news',
    provider: 'google-news-rss'
  };
}).filter(item => item.title && item.url);
const news = gdeltNews.length ? gdeltNews : rssNews;
const geo = Array.isArray(placesRaw.query?.geosearch) ? placesRaw.query.geosearch : [];
const places = geo.slice(0, 10).map(item => ({
  id: `wikipedia-${item.pageid}`,
  name: String(item.title ?? '').replace(/[<>]/g, ' ').slice(0, 180),
  lat: Number(item.lat),
  lng: Number(item.lon),
  distanceM: Number(item.dist ?? 0),
  url: `https://${request.locale === 'de' ? 'de' : request.locale === 'en' ? 'en' : request.locale === 'fr' ? 'fr' : request.locale === 'pt' ? 'pt' : 'es'}.wikipedia.org/?curid=${item.pageid}`,
  sourceType: 'external_place',
  provider: 'wikipedia'
})).filter(item => item.name && Number.isFinite(item.lat) && Number.isFinite(item.lng));
return [{ json: {
  ok: true,
  location: request.location,
  usedDefaultLocation: request.usedDefaultLocation,
  weather,
  imnAlerts,
  news,
  places,
  sources: [
    { provider: 'imn-costa-rica', available: imnAlerts.length > 0, updatedAt: imnAlerts[0]?.publishedAt ?? null },
    { provider: 'open-meteo', available: Boolean(weather), updatedAt: weather?.observedAt ?? null },
    { provider: 'gdelt', available: gdeltNews.length > 0, updatedAt: new Date().toISOString() },
    { provider: 'google-news-rss', available: rssNews.length > 0, updatedAt: new Date().toISOString() },
    { provider: 'wikipedia', available: places.length > 0, updatedAt: new Date().toISOString() }
  ],
  generatedAt: new Date().toISOString()
} }];
